CREATE TABLE semio_brep_document (id INTEGER PRIMARY KEY, schema TEXT NOT NULL, next_label TEXT NOT NULL);
CREATE TABLE semio_brep_vertex (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES semio_brep_document(id), ordinal INTEGER NOT NULL, native_id TEXT NOT NULL, x REAL, y REAL, z REAL, tolerance REAL, x_ieee754_bits INTEGER, x_numeric_class TEXT, y_ieee754_bits INTEGER, y_numeric_class TEXT, z_ieee754_bits INTEGER, z_numeric_class TEXT, tolerance_ieee754_bits INTEGER, tolerance_numeric_class TEXT);
CREATE TABLE semio_brep_edge (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES semio_brep_document(id), ordinal INTEGER NOT NULL, native_id TEXT NOT NULL, start_vertex_id INTEGER NOT NULL REFERENCES semio_brep_vertex(id), end_vertex_id INTEGER NOT NULL REFERENCES semio_brep_vertex(id), curve_id INTEGER NOT NULL REFERENCES semio_brep_curve3(id), tolerance REAL, tolerance_ieee754_bits INTEGER, tolerance_numeric_class TEXT);
CREATE TABLE semio_brep_loop (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES semio_brep_document(id), ordinal INTEGER NOT NULL, native_id TEXT NOT NULL);
CREATE TABLE semio_brep_loop_edge (id INTEGER PRIMARY KEY, loop_id INTEGER NOT NULL REFERENCES semio_brep_loop(id), ordinal INTEGER NOT NULL, edge_id INTEGER NOT NULL REFERENCES semio_brep_edge(id), orientation INTEGER NOT NULL);
CREATE TABLE semio_brep_coedge (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES semio_brep_document(id), ordinal INTEGER NOT NULL, native_id TEXT NOT NULL, edge_id INTEGER NOT NULL REFERENCES semio_brep_edge(id), forward INTEGER NOT NULL, curve_id INTEGER REFERENCES semio_brep_curve2(id), parameter_start REAL, parameter_end REAL, loop_id INTEGER NOT NULL REFERENCES semio_brep_loop(id), next_id INTEGER NOT NULL REFERENCES semio_brep_coedge(id), previous_id INTEGER NOT NULL REFERENCES semio_brep_coedge(id), parameter_start_ieee754_bits INTEGER, parameter_start_numeric_class TEXT, parameter_end_ieee754_bits INTEGER, parameter_end_numeric_class TEXT);
CREATE TABLE semio_brep_face (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES semio_brep_document(id), ordinal INTEGER NOT NULL, native_id TEXT NOT NULL, outer_loop_id INTEGER NOT NULL REFERENCES semio_brep_loop(id), surface_id INTEGER NOT NULL REFERENCES semio_brep_surface(id), orientation INTEGER NOT NULL, tolerance REAL, tolerance_ieee754_bits INTEGER, tolerance_numeric_class TEXT);
CREATE TABLE semio_brep_inner_loop (id INTEGER PRIMARY KEY, face_id INTEGER NOT NULL REFERENCES semio_brep_face(id), ordinal INTEGER NOT NULL, loop_id INTEGER NOT NULL REFERENCES semio_brep_loop(id));
CREATE TABLE semio_brep_shell (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES semio_brep_document(id), ordinal INTEGER NOT NULL, native_id TEXT NOT NULL);
CREATE TABLE semio_brep_shell_face (id INTEGER PRIMARY KEY, shell_id INTEGER NOT NULL REFERENCES semio_brep_shell(id), ordinal INTEGER NOT NULL, face_id INTEGER NOT NULL REFERENCES semio_brep_face(id), orientation INTEGER NOT NULL);
CREATE TABLE semio_brep_solid (id INTEGER PRIMARY KEY, document_id INTEGER NOT NULL REFERENCES semio_brep_document(id), ordinal INTEGER NOT NULL, native_id TEXT NOT NULL);
CREATE TABLE semio_brep_solid_shell (id INTEGER PRIMARY KEY, solid_id INTEGER NOT NULL REFERENCES semio_brep_solid(id), ordinal INTEGER NOT NULL, shell_id INTEGER NOT NULL REFERENCES semio_brep_shell(id), is_void INTEGER NOT NULL);
CREATE TABLE semio_brep_curve3 (id INTEGER PRIMARY KEY, kind TEXT NOT NULL, origin_x REAL, origin_y REAL, origin_z REAL, direction_x REAL, direction_y REAL, direction_z REAL, center_x REAL, center_y REAL, center_z REAL, axis_x REAL, axis_y REAL, axis_z REAL, radius REAL, radius_major REAL, radius_minor REAL, degree INTEGER, origin_x_ieee754_bits INTEGER, origin_x_numeric_class TEXT, origin_y_ieee754_bits INTEGER, origin_y_numeric_class TEXT, origin_z_ieee754_bits INTEGER, origin_z_numeric_class TEXT, direction_x_ieee754_bits INTEGER, direction_x_numeric_class TEXT, direction_y_ieee754_bits INTEGER, direction_y_numeric_class TEXT, direction_z_ieee754_bits INTEGER, direction_z_numeric_class TEXT, center_x_ieee754_bits INTEGER, center_x_numeric_class TEXT, center_y_ieee754_bits INTEGER, center_y_numeric_class TEXT, center_z_ieee754_bits INTEGER, center_z_numeric_class TEXT, axis_x_ieee754_bits INTEGER, axis_x_numeric_class TEXT, axis_y_ieee754_bits INTEGER, axis_y_numeric_class TEXT, axis_z_ieee754_bits INTEGER, axis_z_numeric_class TEXT, radius_ieee754_bits INTEGER, radius_numeric_class TEXT, radius_major_ieee754_bits INTEGER, radius_major_numeric_class TEXT, radius_minor_ieee754_bits INTEGER, radius_minor_numeric_class TEXT);
CREATE TABLE semio_brep_curve3_point (id INTEGER PRIMARY KEY, curve_id INTEGER NOT NULL REFERENCES semio_brep_curve3(id), ordinal INTEGER NOT NULL, x REAL, y REAL, z REAL, x_ieee754_bits INTEGER, x_numeric_class TEXT, y_ieee754_bits INTEGER, y_numeric_class TEXT, z_ieee754_bits INTEGER, z_numeric_class TEXT);
CREATE TABLE semio_brep_curve3_weight (id INTEGER PRIMARY KEY, curve_id INTEGER NOT NULL REFERENCES semio_brep_curve3(id), ordinal INTEGER NOT NULL, value REAL, value_ieee754_bits INTEGER, value_numeric_class TEXT);
CREATE TABLE semio_brep_curve3_knot (id INTEGER PRIMARY KEY, curve_id INTEGER NOT NULL REFERENCES semio_brep_curve3(id), ordinal INTEGER NOT NULL, value REAL, value_ieee754_bits INTEGER, value_numeric_class TEXT);
CREATE TABLE semio_brep_curve2 (id INTEGER PRIMARY KEY, kind TEXT NOT NULL, origin_x REAL, origin_y REAL, direction_x REAL, direction_y REAL, center_x REAL, center_y REAL, x_axis_x REAL, x_axis_y REAL, radius REAL, radius_major REAL, radius_minor REAL, degree INTEGER, origin_x_ieee754_bits INTEGER, origin_x_numeric_class TEXT, origin_y_ieee754_bits INTEGER, origin_y_numeric_class TEXT, direction_x_ieee754_bits INTEGER, direction_x_numeric_class TEXT, direction_y_ieee754_bits INTEGER, direction_y_numeric_class TEXT, center_x_ieee754_bits INTEGER, center_x_numeric_class TEXT, center_y_ieee754_bits INTEGER, center_y_numeric_class TEXT, x_axis_x_ieee754_bits INTEGER, x_axis_x_numeric_class TEXT, x_axis_y_ieee754_bits INTEGER, x_axis_y_numeric_class TEXT, radius_ieee754_bits INTEGER, radius_numeric_class TEXT, radius_major_ieee754_bits INTEGER, radius_major_numeric_class TEXT, radius_minor_ieee754_bits INTEGER, radius_minor_numeric_class TEXT);
CREATE TABLE semio_brep_curve2_point (id INTEGER PRIMARY KEY, curve_id INTEGER NOT NULL REFERENCES semio_brep_curve2(id), ordinal INTEGER NOT NULL, x REAL, y REAL, x_ieee754_bits INTEGER, x_numeric_class TEXT, y_ieee754_bits INTEGER, y_numeric_class TEXT);
CREATE TABLE semio_brep_curve2_weight (id INTEGER PRIMARY KEY, curve_id INTEGER NOT NULL REFERENCES semio_brep_curve2(id), ordinal INTEGER NOT NULL, value REAL, value_ieee754_bits INTEGER, value_numeric_class TEXT);
CREATE TABLE semio_brep_curve2_knot (id INTEGER PRIMARY KEY, curve_id INTEGER NOT NULL REFERENCES semio_brep_curve2(id), ordinal INTEGER NOT NULL, value REAL, value_ieee754_bits INTEGER, value_numeric_class TEXT);
CREATE TABLE semio_brep_surface (id INTEGER PRIMARY KEY, kind TEXT NOT NULL, origin_x REAL, origin_y REAL, origin_z REAL, axis_x REAL, axis_y REAL, axis_z REAL, center_x REAL, center_y REAL, center_z REAL, normal_x REAL, normal_y REAL, normal_z REAL, radius REAL, half_angle REAL, major_radius REAL, minor_radius REAL, u_count INTEGER, v_count INTEGER, degree_u INTEGER, degree_v INTEGER, origin_x_ieee754_bits INTEGER, origin_x_numeric_class TEXT, origin_y_ieee754_bits INTEGER, origin_y_numeric_class TEXT, origin_z_ieee754_bits INTEGER, origin_z_numeric_class TEXT, axis_x_ieee754_bits INTEGER, axis_x_numeric_class TEXT, axis_y_ieee754_bits INTEGER, axis_y_numeric_class TEXT, axis_z_ieee754_bits INTEGER, axis_z_numeric_class TEXT, center_x_ieee754_bits INTEGER, center_x_numeric_class TEXT, center_y_ieee754_bits INTEGER, center_y_numeric_class TEXT, center_z_ieee754_bits INTEGER, center_z_numeric_class TEXT, normal_x_ieee754_bits INTEGER, normal_x_numeric_class TEXT, normal_y_ieee754_bits INTEGER, normal_y_numeric_class TEXT, normal_z_ieee754_bits INTEGER, normal_z_numeric_class TEXT, radius_ieee754_bits INTEGER, radius_numeric_class TEXT, half_angle_ieee754_bits INTEGER, half_angle_numeric_class TEXT, major_radius_ieee754_bits INTEGER, major_radius_numeric_class TEXT, minor_radius_ieee754_bits INTEGER, minor_radius_numeric_class TEXT);
CREATE TABLE semio_brep_surface_point (id INTEGER PRIMARY KEY, surface_id INTEGER NOT NULL REFERENCES semio_brep_surface(id), ordinal INTEGER NOT NULL, x REAL, y REAL, z REAL, x_ieee754_bits INTEGER, x_numeric_class TEXT, y_ieee754_bits INTEGER, y_numeric_class TEXT, z_ieee754_bits INTEGER, z_numeric_class TEXT);
CREATE TABLE semio_brep_surface_weight (id INTEGER PRIMARY KEY, surface_id INTEGER NOT NULL REFERENCES semio_brep_surface(id), ordinal INTEGER NOT NULL, value REAL, value_ieee754_bits INTEGER, value_numeric_class TEXT);
CREATE TABLE semio_brep_surface_knot_u (id INTEGER PRIMARY KEY, surface_id INTEGER NOT NULL REFERENCES semio_brep_surface(id), ordinal INTEGER NOT NULL, value REAL, value_ieee754_bits INTEGER, value_numeric_class TEXT);
CREATE TABLE semio_brep_surface_knot_v (id INTEGER PRIMARY KEY, surface_id INTEGER NOT NULL REFERENCES semio_brep_surface(id), ordinal INTEGER NOT NULL, value REAL, value_ieee754_bits INTEGER, value_numeric_class TEXT);
